"""One-time desktop pairing; tokens and LinkedIn passwords never enter this form."""

# ruff: noqa: E501
CONNECT_PAGE = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Connect this computer · BluQQ</title>
<style>[hidden]{display:none!important}body{font:16px system-ui;background:#f3f5f9;color:#142238;margin:0}main{max-width:550px;margin:7vh auto;background:white;padding:30px;border-radius:16px}input,button,a.btn{box-sizing:border-box;font:inherit;padding:12px;border:1px solid #cbd5e1;border-radius:8px}input{width:100%;margin:12px 0}button,a.btn{cursor:pointer;background:#2759ed;color:white;text-decoration:none;display:inline-block}p{line-height:1.6}#result{white-space:pre-wrap}small{color:#475569}</style>
<main><h1>Connect this computer</h1><p>Your LinkedIn browser and login stay on this PC. Searches from this browser will run here.</p>
<ol><li>On Windows 10/11 (64-bit), <a href="/linkedin-automation/downloads/BluQQ-Worker.zip">download the Windows helper</a>, extract the ZIP and double-click <strong>Start BluQQ Worker.cmd</strong>. Chrome must be installed. The runtime is included; no Python installation, API key or project setup is needed.</li><li><a href="/linkedin-automation/login" target="_blank" rel="noopener">Sign in with your approved email</a> or <a href="/linkedin-automation/admin" target="_blank" rel="noopener">admin username</a>, then return here.</li><li>Enter the code shown by the helper. Check the computer name before connecting.</li></ol>
<p id="signed">Checking signed-in workspace…</p><form id="pair"><label for="code">Helper pairing code</label><input id="code" maxlength="10" pattern="[A-Z2-9]{10}" required autocomplete="off"><button id="check" type="submit">Check computer</button><p id="computer"></p><button id="approve" type="button" hidden>Connect this computer</button></form><p id="result" role="status"></p><p><a href="/linkedin-automation/">Back to dashboard</a></p><small>Pair only the computer you are using. LinkedIn sign-in is requested locally when a search needs it. Mac and Linux helpers are not available in this release.</small></main>
<script>async function account(){try{const r=await fetch('/linkedin-automation/api/auth/me'),v=await r.json();document.getElementById('signed').textContent=r.ok?(v.role==='admin'?'Workspace: Administrator · Shared research':'Workspace: '+v.email):'Sign in with your approved email before connecting.';}catch(e){document.getElementById('signed').textContent='Could not check workspace. Check your connection.';}}account();window.addEventListener('focus',account);const code=document.getElementById('code'),result=document.getElementById('result'),approve=document.getElementById('approve');code.value=(new URLSearchParams(location.search).get('code')||'').toUpperCase();history.replaceState(null,'',location.pathname);code.oninput=()=>{code.value=code.value.toUpperCase();approve.hidden=true;document.getElementById('computer').textContent='';};async function submit(action){const r=await fetch('/linkedin-automation/api/auth/devices/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:code.value})});const v=await r.json();if(!r.ok)throw Error(v.detail||'Could not connect');return v;}document.getElementById('pair').onsubmit=async e=>{e.preventDefault();try{const v=await submit('preview');document.getElementById('computer').textContent='Computer: '+v.label;approve.hidden=false;result.textContent='Confirm this name matches the helper on your PC.';}catch(e){result.textContent=e.message;}};approve.onclick=async()=>{approve.disabled=true;try{await submit('approve');result.textContent='Computer connected. Keep the helper running, then return to the dashboard in this browser and select Search and fetch.';approve.hidden=true;}catch(e){result.textContent=e.message;}finally{approve.disabled=false;}};</script></html>'''
